using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using Racer;using Object=UnityEngine.Object;
public static class CaptureReverseAtlas {
static object P(Vector3 p)=>new{x=p.x,y=p.y,z=p.z};
public static string Main(){EditorApplication.delayCall+=()=>{var original=UnityEngine.SceneManagement.SceneManager.GetActiveScene().path;try{foreach(var direction in new[]{"Forward","Reverse"}){EditorSceneManager.OpenScene("Assets/Scenes/DansBackyard"+direction+".unity");var race=Object.FindAnyObjectByType<RaceDirector>();var c=race.GetComponent<BackyardForwardCourse>();File.WriteAllText("Docs/BackyardReverse/"+direction+"-map.json",Newtonsoft.Json.JsonConvert.SerializeObject(new{direction,route=race.road.points.Select(P),branches=Object.FindObjectsByType<WoodlandRoute>().Select(b=>new{b.title,points=b.points.Select(P)}),gates=race.gates.Select(g=>new{g.name,position=P(g.transform.position)}),flights=c.flightStarts.Select((p,i)=>new{launch=P(p),landing=P(race.road.At(c.landingStations[i],out _))}),properties=race.GetComponent<ExplorationMap>().destinations.Where(d=>d.id=="home"||d.id.StartsWith("property-")).Select(d=>new{d.title,position=P(d.position)})}));
var go=new GameObject("Temporary Backyard atlas camera"){hideFlags=HideFlags.HideAndDontSave};var camera=go.AddComponent<Camera>();camera.CopyFrom(Camera.main);camera.enabled=false;camera.orthographic=true;camera.orthographicSize=213.333333f;camera.aspect=1.5f;camera.nearClipPlane=.1f;camera.farClipPlane=1200;camera.transform.SetPositionAndRotation(new(280,700,-6.666667f),Quaternion.LookRotation(Vector3.down,Vector3.forward));var rt=new RenderTexture(4800,3200,24);var old=RenderTexture.active;var tex=new Texture2D(4800,3200,TextureFormat.RGB24,false);try{camera.targetTexture=rt;camera.Render();RenderTexture.active=rt;tex.ReadPixels(new Rect(0,0,4800,3200),0,0);tex.Apply();File.WriteAllBytes("Docs/BackyardReverse/"+direction+"-base.png",tex.EncodeToPNG());}finally{RenderTexture.active=old;camera.targetTexture=null;rt.Release();Object.DestroyImmediate(tex);Object.DestroyImmediate(rt);Object.DestroyImmediate(go);}}
File.WriteAllText("Docs/BackyardReverse/atlas-capture-done.txt","Two actual saved Backyard scenes captured with exact world registration; no scene saves.");}catch(Exception e){File.WriteAllText("Docs/BackyardReverse/atlas-capture-error.txt",e.ToString());}finally{EditorSceneManager.OpenScene(original);}};return "Capture separately viewable Forward/Reverse atlas layers";}
}
